package dev.kubejseditor.verification;

import dev.kubejseditor.client.*;
import dev.kubejseditor.model.*;
import dev.kubejseditor.recipe.*;
import dev.kubejseditor.runtime.*;
import dev.kubejseditor.storage.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import java.nio.file.*;
import java.util.*;

/** Real JVM boots verify registration removal, UI confirmation and rollback of the final item. */
@EventBusSubscriber(modid="kubejs_editor_verification",value=Dist.CLIENT)
public final class ClientAuthoringVerification {
    private static int phase,ticks,checks,shotDelay;private static String shot,preserved;private static WorkspaceScreen screen;private static EditorRuntime.ReloadResult result;
    private static final String BLOCK="kubejs:removal_block",ITEM="kubejs:removal_item",KEEP="kubejs:removal_keep",PENDING="authoring:unrelated";
    private static Path root(){return Minecraft.getInstance().gameDirectory.toPath();}
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static Object get(String key)throws Exception{var f=WorkspaceScreen.class.getDeclaredField(key);f.setAccessible(true);return f.get(screen);}
    private static void set(String key,Object value)throws Exception{var f=WorkspaceScreen.class.getDeclaredField(key);f.setAccessible(true);f.set(screen,value);}
    private static Object call(String name,Class<?>[] types,Object... args)throws Exception{for(Class<?> c=WorkspaceScreen.class;c!=null;c=c.getSuperclass())try{var m=c.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(screen,args);}catch(NoSuchMethodException ignored){}throw new NoSuchMethodException(name);}
    private static void call(String name)throws Exception{call(name,new Class[]{});}
    private static void frame()throws Exception{call("rebuildWidgets");}
    private static void click(String text){var b=Minecraft.getInstance().screen.children().stream().filter(c->c instanceof Button v&&v.getMessage().getString().equals(text)).map(c->(Button)c).findFirst().orElseThrow(()->new AssertionError("Missing button "+text));check(b.active,"Button active: "+text);b.onPress();}
    @SuppressWarnings("unchecked") private static List<ChoiceScreen.Choice> choices()throws Exception{var f=ChoiceScreen.class.getDeclaredField("choices");f.setAccessible(true);return (List<ChoiceScreen.Choice>)f.get(Minecraft.getInstance().screen);}
    private static void selectItem(String id)throws Exception{call("selectItem",new Class[]{EditorProject.ItemDraft.class},EditorRuntime.state().applied.items.get(id));}
    private static void capture(String name){shot=name;shotDelay=8;}
    private static boolean exists(String id){return BuiltInRegistries.ITEM.containsKey(ResourceLocation.parse(id));}
    private static void clear()throws Exception{set("recipe",null);set("item",null);set("dirty",false);for(var op:new ArrayList<>(EditorRuntime.operations()))EditorRuntime.cancel(op);frame();}
    private static void finish(int stage)throws Exception{Files.writeString(root().resolve("authoring-stage"+stage+".json"),"{\"passed\":true,\"checks\":"+checks+"}");Minecraft.getInstance().stop();phase=99;}
    @SubscribeEvent public static void tick(ClientTickEvent.Post event){
        if(!Boolean.getBoolean("kubejs.editor.verifyAuthoring")||phase==99)return;var mc=Minecraft.getInstance();ticks++;
        if(shot!=null&&--shotDelay<=0){Screenshot.grab(mc.gameDirectory,"authoring-"+shot+".png",mc.getMainRenderTarget(),c->{});shot=null;}
        try{
            if(phase==0&&mc.screen instanceof TitleScreen&&ticks>100){mc.createWorldOpenFlows().openWorld("EditorVerification",()->{});phase=1;ticks=0;return;}
            if(phase==1&&mc.level!=null&&mc.player!=null&&ticks>120){
                EditorRuntime.project();if(EditorRuntime.state().activation!=null){if(ticks>700)throw new AssertionError("Restart activation: "+EditorRuntime.activationError);return;}
                screen=new WorkspaceScreen();mc.setScreen(screen);
                for(String mod:List.of("jei","create","createvintageneoforged","aeronautics","ftblibrary","inventoryprofilesnext"))check(net.neoforged.fml.ModList.get().isLoaded(mod),"Compatibility mod: "+mod);
                phase=Files.exists(root().resolve("authoring-stage7.json"))?80:Files.exists(root().resolve("authoring-stage6.json"))?70:Files.exists(root().resolve("authoring-stage5.json"))?66:Files.exists(root().resolve("authoring-stage4.json"))?60:Files.exists(root().resolve("authoring-stage3.json"))?50:Files.exists(root().resolve("authoring-stage2.json"))?40:Files.exists(root().resolve("authoring-stage1.json"))?20:2;ticks=0;return;
            }
            if(phase<2||ticks<25)return;if(ticks>1600)throw new AssertionError("Timeout phase "+phase);
            switch(phase){
                case 2 -> {clear();click("+配方");check(choices().stream().anyMatch(c->c.text().contains("工作台")),"Root has vanilla workstations");check(choices().stream().noneMatch(c->c.searchText().startsWith("create:")),"Create stations are not flattened into root");check(choices().stream().anyMatch(c->c.text().equals("机械动力")),"Root has Create category");capture("recipe-categories");}
                case 3 -> {var parent=mc.screen;click("机械动力");check(mc.screen instanceof ChoiceScreen,"Create opens a second picker");check(choices().stream().anyMatch(c->c.text().equals("鼓风机加工")),"Fan stays grouped inside Create");check(choices().stream().filter(c->c.text().equals("复古 · 真空腔室")).count()==1,"Vintage chamber states stay grouped");check(choices().stream().noneMatch(c->c.searchText().startsWith("minecraft:")),"Create submenu excludes vanilla");capture("create-submenu");mc.screen.onClose();check(mc.screen==parent,"Submenu back returns to root picker");}
                case 4 -> {click("机械动力");var choice=choices().stream().filter(c->c.searchText().equals("create:mixing")).findFirst().orElseThrow();choice.action().run();check(mc.screen==screen,"Choosing nested station returns to workspace");clear();call("createItem",new Class[]{String.class,boolean.class},"basic",true);var item=(EditorProject.ItemDraft)get("item");call("confirmDeleteItem",new Class[]{String.class},item.id);check(mc.screen instanceof ConfirmScreen,"Unapplied registration requires confirmation");click("取消");check(EditorRuntime.project().items.containsKey(item.id),"Cancelling confirmation preserves draft");call("confirmDeleteItem",new Class[]{String.class},item.id);click("确认删除");check(!EditorRuntime.project().items.containsKey(item.id)&&get("item")==null,"Confirmed draft deletion clears selection and queue");screen.onClose();screen=new WorkspaceScreen();mc.setScreen(screen);check(EditorRuntime.project().items.isEmpty(),"Deleted draft never resurrects when reopened");}
                case 5 -> {
                    var good=new EditorProject.RecipeDraft("authoring:good",RecipeAdapters.get("minecraft:smelting").newRecipe());EditorRuntime.project().recipes.put(good.id,good);
                    var bad=new EditorProject.RecipeDraft("authoring:bad",RecipeAdapters.get("create:cutting").newRecipe());while(bad.data.getAsJsonArray("results").size()<6)bad.data.getAsJsonArray("results").add(RecipeAdapters.parse("{id:'minecraft:iron_nugget'}"));EditorRuntime.project().recipes.put(bad.id,bad);
                    call("selectRecipe",new Class[]{EditorProject.RecipeDraft.class,boolean.class},bad,false);click("查看代码");check((int)get("tab")==3&&((String)call("reviewText",new Class[]{})).contains("原始数据"),"Invalid record remains inspectable in unified code page");check(screen.children().stream().noneMatch(c->c instanceof Button b&&b.getMessage().getString().equals("查看详情")),"No duplicate details entry");capture("code-invalid");
                }
                case 6 -> {click("检查结果");check(((String)call("reviewText",new Class[]{})).contains("6"),"Checks identify the six-output recipe");click("文件差异");check(((String)call("reviewText",new Class[]{})).contains("修正"),"Diff explains validation block without hiding code");click("代码");set("codeIndex",0);frame();check(((String)call("reviewText",new Class[]{})).contains("event.custom"),"Valid record has generated code despite another invalid draft");mc.options.guiScale().set(3);mc.resizeDisplay();capture("code-scale3");}
                case 7 -> {check(WorkspaceJeiPlugin.runtime.getIngredientListOverlay().isListDisplayed(),"JEI remains visible on unified page");mc.options.guiScale().set(2);mc.resizeDisplay();set("tab",0);clear();
                    for(String kind:List.of("basic","block","food")){var item=new EditorProject.ItemDraft();ItemKinds.initialize(item,kind);item.id=kind.equals("block")?BLOCK:kind.equals("food")?KEEP:ITEM;item.name="删除验证"+kind;item.tooltip.add("确认删除测试");EditorRuntime.project().items.put(item.id,item);
                        if(!kind.equals("food"))EditorResources.stageTexture(root(),EditorRuntime.project(),item,Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aB2kAAAAASUVORK5CYII="));}
                    EditorRuntime.saveDraft();check(EditorRuntime.validationIssues().isEmpty(),"Registration fixtures validate");var review=EditorRuntime.review();check(review.restartRequired(),"Registration requires restart");EditorRuntime.apply(review);check(EditorRuntime.locked(),"Startup transaction locks repeat submission");finish(1);return;}
                case 20 -> {check(exists(BLOCK)&&exists(ITEM)&&exists(KEEP),"All three items registered after restart");check(BuiltInRegistries.BLOCK.containsKey(ResourceLocation.parse(BLOCK)),"Block is registered in both registries");check(EditorRuntime.project().items.isEmpty(),"Successful registration clears pending items");selectItem(BLOCK);
                    var dep=new EditorProject.RecipeDraft("authoring:dependent",RecipeAdapters.parse("{type:'minecraft:crafting_shapeless',ingredients:[{item:'kubejs:removal_block'}],result:{id:'minecraft:diamond'}}"));EditorRuntime.project().recipes.put(dep.id,dep);
                    check(EditorRuntime.itemDeletionBlockers(BLOCK).stream().anyMatch(s->s.contains(dep.id)),"Pending dependencies block registration deletion");call("confirmDeleteItem",new Class[]{String.class},BLOCK);check(mc.screen instanceof TextScreen&&EditorRuntime.state().activation==null,"Blocked delete lists references and writes nothing");mc.screen.onClose();EditorRuntime.cancel(new PendingOperation("recipe",dep.id,"配方生成"));
                    Path manual=root().resolve("kubejs/server_scripts/manual-reference.js");Files.writeString(manual,"// Inspect "+BLOCK+" before removal\n");try{check(EditorRuntime.itemDeletionBlockers(BLOCK).stream().anyMatch(s->s.contains("manual-reference.js:1")),"Hand-written reference has source line");}finally{Files.delete(manual);}
                    Path startup=root().resolve(EditorRuntime.state().outputPath(WorkspaceState.GENERATED.get(1)));byte[] before=Files.readAllBytes(startup);try{Files.writeString(startup,new String(before,java.nio.charset.StandardCharsets.UTF_8)+"\n// external edit\n");boolean failed=false;try{EditorRuntime.deleteRegisteredItem(BLOCK);}catch(Exception expected){failed=expected.getMessage().contains("外部修改");}check(failed&&EditorRuntime.state().activation==null,"External edit blocks deletion without submitting");}finally{Files.write(startup,before);}
                    var unrelated=new EditorProject.RecipeDraft(PENDING,RecipeAdapters.get("create:cutting").newRecipe());while(unrelated.data.getAsJsonArray("results").size()<6)unrelated.data.getAsJsonArray("results").add(RecipeAdapters.parse("{id:'minecraft:iron_nugget'}"));EditorRuntime.project().recipes.put(PENDING,unrelated);EditorRuntime.saveDraft();
                    call("confirmDeleteItem",new Class[]{String.class},BLOCK);check(mc.screen instanceof ConfirmScreen,"Applied block requires confirmation");capture("delete-confirmation");}
                case 21 -> {click("取消");check(EditorRuntime.state().activation==null&&exists(BLOCK)&&EditorRuntime.state().applied.items.containsKey(BLOCK),"Cancelled deletion preserves registration and files");call("confirmDeleteItem",new Class[]{String.class},BLOCK);click("确认删除");var a=EditorRuntime.state().activation;check(a!=null&&a.restart&&a.deletedItems.contains(BLOCK)&&!a.desired.items.containsKey(BLOCK),"Confirmed block deletion persists restart transaction");check(exists(BLOCK),"Live registry is preserved until restart");check(EditorRuntime.project().recipes.containsKey(PENDING)&&ProjectStore.read(root()).recipes.containsKey(PENDING),"Independent invalid draft is preserved on disk");String js=Files.readString(root().resolve(WorkspaceState.GENERATED.get(1)));check(!js.contains(BLOCK)&&js.contains(ITEM)&&js.contains(KEEP),"Only requested registration removed from startup code");check(!Files.exists(root().resolve("kubejs/assets/kubejs_editor/textures/item/kubejs/removal_block.png"))&&Files.exists(root().resolve("kubejs/assets/kubejs_editor/textures/item/kubejs/removal_item.png")),"Only unused target texture is removed");check(EditorRuntime.locked(),"Waiting deletion blocks repeat submission");capture("delete-waiting");}
                case 22 -> {finish(2);return;}
                case 40 -> {check(!exists(BLOCK)&&!BuiltInRegistries.BLOCK.containsKey(ResourceLocation.parse(BLOCK)),"Block and BlockItem are absent after real JVM restart");check(!EditorRuntime.state().applied.items.containsKey(BLOCK)&&exists(ITEM)&&exists(KEEP),"Deletion leaves no extra applied record and preserves other items");check(EditorRuntime.project().recipes.containsKey(PENDING),"Unrelated draft survives restart and activation");selectItem(ITEM);call("confirmDeleteItem",new Class[]{String.class},ITEM);click("确认删除");check(EditorRuntime.state().activation.deletedItems.contains(ITEM),"Ordinary item uses the same confirmed removal path");finish(3);return;}
                case 50 -> {check(!exists(ITEM)&&!exists(BLOCK)&&exists(KEEP),"Both deleted registrations stay absent; keep item survives");check(!EditorRuntime.state().applied.items.containsKey(ITEM)&&!EditorRuntime.state().applied.items.containsKey(BLOCK),"Completed deletions do not create modification records");check(EditorRuntime.state().activation==null&&EditorRuntime.project().recipes.containsKey(PENDING),"Final activation verifies absence and preserves pending work");check(EditorRuntime.state().applied.items.get(KEEP).register,"Remaining registration retains generator ownership");finish(4);return;}
                case 60 -> {
                    String before=ProjectStore.JSON.toJson(EditorRuntime.project());var oak=EditorRuntime.recipes().stream().filter(r->r.id().equals("minecraft:oak_button")).findFirst().orElseThrow();
                    call("selectLoaded",new Class[]{EditorRuntime.Loaded.class},oak);click("查看代码");check(((String)call("reviewText",new Class[]{})).contains("minecraft:oak_button"),"An unmodified loaded recipe is inspectable");check(before.equals(ProjectStore.JSON.toJson(EditorRuntime.project())),"Inspecting loaded recipe creates no pending operation");clear();
                    for(String id:List.of("minecraft:oak_button","minecraft:stone_button","authoring:added")){var draft=new EditorProject.RecipeDraft(id,RecipeAdapters.parse("{type:'minecraft:crafting_shapeless',ingredients:[{item:'minecraft:iron_ingot'}],result:{id:'minecraft:oak_button'}}"));draft.operation=id.equals("minecraft:stone_button")?"remove":id.equals("authoring:added")?"add":"replace";draft.origin=id.equals("authoring:added")?"add":"existing";EditorRuntime.project().recipes.put(id,draft);}
                    EditorRuntime.saveDraft();var review=EditorRuntime.review();check(!review.restartRequired(),"Recipe confirmation fixtures require only reload");EditorRuntime.apply(review);result=null;EditorRuntime.reloadResult(false,r->result=r);
                }
                case 61 -> {if(result==null)return;check(result.success(),"Confirmation fixtures applied");var pending=new EditorProject.RecipeDraft(PENDING,RecipeAdapters.get("minecraft:smelting").newRecipe());EditorRuntime.project().recipes.put(PENDING,pending);EditorRuntime.saveDraft();preserved=ProjectStore.JSON.toJson(EditorRuntime.project());
                    set("tab",4);set("filter","minecraft:oak_button");frame();long generation=ScriptIndex.serverGeneration;
                    var row=mc.screen.children().stream().filter(c->c instanceof Button b&&b.getMessage().getString().equals("×")&&b.getWidth()==18).map(c->(Button)c).findFirst().orElseThrow();row.onPress();check(mc.screen instanceof ConfirmScreen,"Applied row deletion has confirmation");click("取消");check(EditorRuntime.state().activation==null&&ScriptIndex.serverGeneration==generation&&EditorRuntime.state().applied.recipes.containsKey("minecraft:oak_button"),"Cancelling applied row does not reload or remove rule");call("revokeAppliedRecipe",new Class[]{String.class},"minecraft:oak_button");capture("recipe-revert-confirmation");}
                case 62 -> {click("确认撤销");check(EditorRuntime.busy()||EditorRuntime.state().activation!=null,"Confirmed revocation starts independent reload");}
                case 63 -> {if(EditorRuntime.busy()||EditorRuntime.state().activation!=null)return;check(EditorRuntime.activationError.isBlank()&&!EditorRuntime.state().applied.recipes.containsKey("minecraft:oak_button"),"Replacement rule removed after confirmation");var recipe=mc.getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse("minecraft:oak_button")).orElseThrow();check(recipe.value().getIngredients().getFirst().test(new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.OAK_PLANKS)),"Replacement revoke restores original oak planks");check(preserved.equals(ProjectStore.JSON.toJson(EditorRuntime.project())),"Confirmed revoke preserves unrelated pending work");call("revokeAppliedRecipe",new Class[]{String.class},"minecraft:stone_button");check(mc.screen instanceof ConfirmScreen,"Re-enabling a disabled recipe also requires confirmation");click("取消");check(mc.getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse("minecraft:stone_button")).isEmpty(),"Cancel leaves disabled recipe disabled");call("revokeAppliedRecipe",new Class[]{String.class},"minecraft:stone_button");click("确认撤销");}
                case 64 -> {if(EditorRuntime.busy()||EditorRuntime.state().activation!=null)return;check(mc.getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse("minecraft:stone_button")).isPresent()&&!EditorRuntime.state().applied.recipes.containsKey("minecraft:stone_button"),"Confirmed disable revocation restores source recipe");call("revokeAppliedRecipe",new Class[]{String.class},"authoring:added");check(mc.screen instanceof ConfirmScreen,"Removing an added recipe requires confirmation");click("取消");check(mc.getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse("authoring:added")).isPresent(),"Cancel keeps added recipe");call("revokeAppliedRecipe",new Class[]{String.class},"authoring:added");click("确认撤销");}
                case 65 -> {if(EditorRuntime.busy()||EditorRuntime.state().activation!=null)return;check(mc.getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse("authoring:added")).isEmpty()&&!EditorRuntime.state().applied.recipes.containsKey("authoring:added"),"Confirmed added-recipe removal leaves no disable record");check(preserved.equals(ProjectStore.JSON.toJson(EditorRuntime.project())),"All three revocations preserve other pending work");check(EditorRuntime.activationError.isBlank(),"No reload validation errors");finish(5);return;}
                case 66 -> {check(EditorRuntime.state().applied.items.size()==1&&exists(KEEP),"Final item fixture is active");selectItem(KEEP);call("confirmDeleteItem",new Class[]{String.class},KEEP);click("确认删除");check(EditorRuntime.state().activation.desired.items.isEmpty(),"Final registration removed from desired state");for(String path:List.of(WorkspaceState.GENERATED.get(1),WorkspaceState.GENERATED.get(2),"kubejs/assets/kubejs_editor/lang/zh_cn.json","kubejs/assets/kubejs_editor/lang/en_us.json"))check(!Files.exists(root().resolve(path)),"Empty generated item file is removed: "+path);check(Files.readString(root().resolve("kubejs/config/kubejs_editor/applied-items.json")).trim().equals("[]"),"Managed ID list is emptied");check(EditorRuntime.project().recipes.containsKey(PENDING),"Final deletion still preserves other pending work");finish(6);return;}
                case 70 -> {check(!exists(KEEP)&&EditorRuntime.state().applied.items.isEmpty(),"Final item is absent after restart with no stale registration record");check(EditorRuntime.state().activation==null&&EditorRuntime.activationError.isBlank(),"Empty registration set verifies successfully");EditorRuntime.rollback();check(EditorRuntime.state().applied.items.containsKey(KEEP)&&EditorRuntime.requiresRestart(),"Rollback restores registration files and requires restart");check(EditorRuntime.project().recipes.containsKey(PENDING),"Rollback preserves pre-transaction pending operations");finish(7);return;}
                case 80 -> {check(exists(KEEP)&&!exists(ITEM)&&!exists(BLOCK),"Rollback restores exactly the final item after real restart");check(EditorRuntime.state().applied.items.size()==1&&EditorRuntime.state().applied.items.containsKey(KEEP),"Rollback restores correct applied ownership");check(!EditorRuntime.locked()&&EditorRuntime.activationError.isBlank(),"Rollback restart leaves editor usable");check(EditorRuntime.project().recipes.containsKey(PENDING),"Other pending work survives removal, rollback and restart");finish(8);return;}
            }
            phase++;ticks=0;
        }catch(Throwable error){try{Files.writeString(root().resolve("authoring-failure.json"),"{\"phase\":"+phase+",\"error\":"+ProjectStore.JSON.toJson(error.toString())+"}");}catch(Exception ignored){}error.printStackTrace();mc.stop();phase=99;}
    }
}
